/**
 * Real Chromium/Three.js visual stress lab. Each setting is compiled from a
 * single batch JSON input with separately bounded scene graphs. QA data is
 * hand-authored and MUST NOT be described as generated by Gemini.
 */
import * as THREE from 'three';
import {SceneProgram3D} from '../../src/studio/explainer/sceneProgram/stage3d';
import {buildComplexWorldBatchDemo} from '../../src/studio/explainer/sceneProgram/planner/complexWorldBatchDemo';

const W=720,H=1280,canvas=document.querySelector<HTMLCanvasElement>('#scene')!;
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});
renderer.setSize(W,H,false);
renderer.setPixelRatio(1);
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;
const batch=buildComplexWorldBatchDemo();
const stages=batch.clips.map(c=>new SceneProgram3D(c.program,c.sources));
const overlay=document.createElement('canvas');
overlay.width=W;overlay.height=H;
const ctx=overlay.getContext('2d')!;
const labels=[
  'ARCA DE NOÉ — COSTA E ANIMAIS',
  'PRISÃO DE SEGURANÇA MÁXIMA',
  'MOTOCICLETA ESPORTIVA 3D'
];
const required=[
  ['ark','ark-hull','ark-hatch','animals','ocean'],
  ['compound','compound-gate','patrol','compound-towers'],
  ['bike','bike-fairing','bike-fwheel','bike-rwheel','street']
];
const seek=(t:number)=>{
  const safe=Math.max(0,Math.min(17.9999,t));
  const index=Math.min(2,Math.floor(safe/6));
  const local=safe-index*6;
  const clip=batch.clips[index],stage=stages[index];
  stage.render(renderer,local,W,H);
  ctx.clearRect(0,0,W,H);
  ctx.drawImage(canvas,0,0);
  ctx.fillStyle='rgba(7,18,29,.9)';
  ctx.fillRect(0,H-190,W,190);
  ctx.fillStyle='#D49B62';
  ctx.fillRect(34,H-170,84,5);
  ctx.fillStyle='#FAFBFC';
  ctx.font='bold 27px sans-serif';
  ctx.fillText(labels[index],34,H-113);
  ctx.font='21px sans-serif';
  ctx.fillStyle='#DCE9EE';
  const phrase=clip.sources[local<3?0:1].text;
  const cut=phrase.lastIndexOf(' ',64);
  const split=phrase.length>64?Math.max(20,cut):phrase.length;
  ctx.fillText(phrase.slice(0,split),34,H-73);
  if(split<phrase.length)ctx.fillText(phrase.slice(split).trim(),34,H-45);
  const nodes=Object.fromEntries(required[index].map(id=>{
    const obj=stage.nodes.get(id);
    return [id,obj?{
      position:obj.position.toArray(),
      rotation:obj.rotation.toArray().slice(0,3),
      bounds:new THREE.Box3().setFromObject(obj).getSize(new THREE.Vector3()).toArray()
    }:null];
  }));
  const water=clip.program.nodes.filter(n=>n.geometry?.shape==='water').map(n=>{
    const mesh=stage.nodes.get(n.id) as THREE.Mesh<THREE.BufferGeometry>;
    const positions=mesh.geometry.getAttribute('position');
    return {id:n.id,samples:[0,Math.floor(positions.count/2),positions.count-1]
      .map(i=>positions.getY(i))};
  });
  return {
    index,setting:clip.id,time:safe,local,
    nodes,water,camera:stage.camera.position.toArray(),
    viewNodes:clip.program.nodes.length,
    parts:clip.audit.objectParts,
    worldObjects:clip.audit.objectCount,
    sceneryRegions:clip.audit.sceneryRegions
  };
};
(window as any).__complexWorlds={
  info:{frames:432,duration:18,fps:24,
    scenes:batch.clips.map(x=>x.id),
    nodes:batch.clips.map(x=>x.program.nodes.length),
    audit:batch.audit,generatedBy:'hand-authored stress JSON, not Gemini'},
  seek,
  frame:()=>overlay.toDataURL('image/png')
};
seek(0);
document.body.dataset.ready='complex-worlds-3d';
